// 数据划分的数学表达
class DataPartitioner {
public:
    struct Partition {
        int32_t start_index;
        int32_t length;
        bool is_valid;
    };

    // 计算每个核的数据分区
    static Partition calculate_partition(int32_t total_length, 
                                       int32_t tile_length,
                                       int32_t block_idx,
                                       int32_t block_dim) {
        Partition part;
        part.start_index = block_idx * tile_length;

        // 处理边界情况：最后一个核可能处理较少数据
        if (part.start_index >= total_length) {
            part.is_valid = false;
            part.length = 0;
        } else {
            part.is_valid = true;
            part.length = std::min(tile_length, 
                                 total_length - part.start_index);
        }
        return part;
    }
};
```

